private trySwitchOnCompletion(sessionId: string, completed: boolean): SegmentSwitchResult | null {
  if (!completed) return null;
  const __mutHandoff = this.tools.get("handoff_to_new_session");
  if (__mutHandoff) void __mutHandoff.execute({ task: "switch-mutation" }, { sessionId, cwd: "" } as any);
